import { Key } from "react";

import { ToolType } from "../../../types/tool";
import { ToolValidationInfo } from "../toolEditor";

import { ComboBox } from "@mendix/ide-ui-components/dropdown/combobox/ComboBox";
import { DropdownListBoxItem } from "@mendix/ide-ui-components/dropdown/dropdown/DropdownListBox";
import { ToolTypes } from "../../../constants/mcp";

const toolTypeOptions: { key: ToolType; caption: string }[] = [
    { key: ToolTypes.Microflow, caption: "Microflow tool" },
    { key: ToolTypes.MCP, caption: "MCP tool" },
];

interface ToolTypeComboBoxProps {
    selectedKey: ToolType;
    validationInfo: ToolValidationInfo;
    onToolTypeChange: (key: Key | null) => void;
}

const ToolTypeComboBox: React.FC<ToolTypeComboBoxProps> = ({ selectedKey, validationInfo, onToolTypeChange }) => {
    return (
        <ComboBox
            aria-label="Tool type"
            label="Tool type"
            selectedKey={selectedKey}
            validate={() => validationInfo.isValidType}
            onSelectionChange={onToolTypeChange}
        >
            {toolTypeOptions.map((option) => (
                <DropdownListBoxItem key={option.key} id={option.key}>
                    {option.caption}
                </DropdownListBoxItem>
            ))}
        </ComboBox>
    );
};

export default ToolTypeComboBox;
